fn main() -> Int {
  var data = Vec[Int].new();
  data.push(1);
  data.push(2);
  {
    let r = &data;  // Read borrow starts
    io.println(r.len());
  }  // Read borrow ends here
  {
    let w = &mut data;  // Write borrow starts (read borrow is dead)
    w.push(3);
  }  // Write borrow ends here
  return data.len() as Int;
}
